import java.util.*;

class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> frequency = new HashMap<>();
        for (String word : words) {
            frequency.put(word, frequency.getOrDefault(word, 0) + 1);
        }

        List<String> unique = new ArrayList<>(frequency.keySet());
        unique.sort((a, b) -> {
            int byCount = Integer.compare(frequency.get(b), frequency.get(a));
            if (byCount != 0) {
                return byCount;
            }
            return a.compareTo(b);
        });

        return new ArrayList<>(unique.subList(0, k));
    }
}

import java.util.*;

class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> frequency = new HashMap<>();
        for (String word : words) {
            frequency.put(word, frequency.getOrDefault(word, 0) + 1);
        }

        PriorityQueue<String> heap = new PriorityQueue<>((a, b) -> {
            int byCount = Integer.compare(frequency.get(a), frequency.get(b));
            if (byCount != 0) {
                return byCount;
            }
            return b.compareTo(a);
        });

        for (String word : frequency.keySet()) {
            heap.offer(word);
            if (heap.size() > k) {
                heap.poll();
            }
        }

        LinkedList<String> result = new LinkedList<>();
        while (!heap.isEmpty()) {
            result.addFirst(heap.poll());
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> frequency = new HashMap<>();
        for (String word : words) {
            frequency.put(word, frequency.getOrDefault(word, 0) + 1);
        }

        List<String>[] buckets = new List[words.length + 1];
        for (Map.Entry<String, Integer> entry : frequency.entrySet()) {
            int count = entry.getValue();
            if (buckets[count] == null) {
                buckets[count] = new ArrayList<>();
            }
            buckets[count].add(entry.getKey());
        }

        List<String> answer = new ArrayList<>();
        for (int count = buckets.length - 1; count >= 0 && answer.size() < k; count--) {
            if (buckets[count] == null) {
                continue;
            }
            Collections.sort(buckets[count]);
            for (String word : buckets[count]) {
                answer.add(word);
                if (answer.size() == k) {
                    break;
                }
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word;
    }

    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> frequency = new HashMap<>();
        int maxFrequency = 0;
        for (String word : words) {
            int count = frequency.getOrDefault(word, 0) + 1;
            frequency.put(word, count);
            maxFrequency = Math.max(maxFrequency, count);
        }

        TrieNode[] buckets = new TrieNode[maxFrequency + 1];
        for (Map.Entry<String, Integer> entry : frequency.entrySet()) {
            int count = entry.getValue();
            if (buckets[count] == null) {
                buckets[count] = new TrieNode();
            }
            insert(buckets[count], entry.getKey());
        }

        List<String> result = new ArrayList<>();
        for (int count = maxFrequency; count >= 1 && result.size() < k; count--) {
            if (buckets[count] != null) {
                collect(buckets[count], result, k);
            }
        }
        return result;
    }

    private void insert(TrieNode root, String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int index = c - 'a';
            if (node.children[index] == null) {
                node.children[index] = new TrieNode();
            }
            node = node.children[index];
        }
        node.word = word;
    }

    private void collect(TrieNode node, List<String> result, int k) {
        if (node == null || result.size() == k) {
            return;
        }
        if (node.word != null) {
            result.add(node.word);
            if (result.size() == k) {
                return;
            }
        }
        for (TrieNode child : node.children) {
            collect(child, result, k);
            if (result.size() == k) {
                return;
            }
        }
    }
}
